using System;
namespace LoopPedal {
static class FxParameters {
 public static int Canonical(int k){return k==9?5:k==11?7:k==16?6:k==17?8:k;}
 public static string Name(int k,MasterFx f){return new[]{"REVERB","DECAY","DELAY","TIME","FEEDBACK","GRAIN","GRAIN SIZE","PITCH","SPRAY","GRAIN",f.GrainMode==1?"POSITION":"WINDOW","PITCH","FEEDBACK","CLOUDY","TEXTURE","SPREAD","GRAIN SIZE","SPRAY","FILTER","TONE","DRY / WET","DIRECTION","LO-FI","DENSITY","POSITION","POSITION"}[k];}
 public static float Get(MasterFx f,int k){return k==25?f.Position/1.5f:k>=21?GrainSwitches.normalized(f,k):k==20?f.GrainMix:k==19?f.HallTone:k==18?(f.Filter+1)/2:k==0?f.Reverb:k==1?f.Size:k==2?f.Delay:k==3?(f.DelaySync?f.Division/5f:(f.Time-.04f)/1.46f):k==4?f.Feedback/.85f:k==5||k==9?f.Grain:k==6||k==16?(float)(Math.Log(f.GrainSize/.002)/Math.Log(500)):k==7||k==11?(f.GrainPitch+12)/24:k==8||k==17?f.Spray/4:k==10?(f.GrainMode==1?f.Position/1.5f:(f.CloudWindow-.04f)/1.46f):k==12?(f.CloudFeedback/.92f+1)/2:k==13?f.Cloudy:k==14?f.Texture:f.Spread/2;}
 public static void Set(MasterFx f,int k,float value){float v=Math.Max(0,Math.Min(1,value));if(k==25){f.Position=v*1.5f;return;}if(k>=21){GrainSwitches.setNormalized(f,k,v);return;}if(k==20)f.GrainMix=v;if(k==19)f.HallTone=v;if(k==18)f.Filter=Math.Abs(v-.5f)<.005f?0:v*2-1;if(k==0)f.Reverb=v;if(k==1)f.Size=v;if(k==2)f.Delay=v;if(k==3){if(f.DelaySync)f.Division=(int)Math.Round(v*5);else f.Time=.04f+v*1.46f;}if(k==4)f.Feedback=v*.85f;if(k==5||k==9)f.Grain=v;if(k==6||k==16)f.GrainSize=(float)(.002*Math.Pow(500,v));if(k==7||k==11)f.GrainPitch=v*24-12;if(k==8||k==17)f.Spray=v*4;if(k==10){if(f.GrainMode==1)f.Position=v*1.5f;else f.CloudWindow=.04f+v*1.46f;}if(k==12)f.CloudFeedback=(v*2-1)*.92f;if(k==13)f.Cloudy=v;if(k==14)f.Texture=v;if(k==15)f.Spread=v*2;}
 public static float Default(MasterFx f,int k){if(k==25)return .1f;return k==3?(f.DelaySync?.4f:(.375f-.04f)/1.46f):k==10?(f.GrainMode==1?.1f:(.25f-.04f)/1.46f):new[]{0f,.5f,0f,.4f,.35f/.85f,0f,(float)(Math.Log(45)/Math.Log(500)),.5f,.075f,0f,0f,.5f,(.45f/.92f+1)/2,.65f,.65f,.375f,(float)(Math.Log(45)/Math.Log(500)),.075f,.5f,.5f,.5f}[k];}
 public static string Label(MasterFx f,int k){return k==8||k==17?(f.Spray*500).ToString("0")+"ms":k==15?(f.Spread*100).ToString("0")+"%":k==25?(f.Position*1000).ToString("0")+"ms":k==20?(f.GrainMix<.001f?"DRY":f.GrainMix>.999f?"WET":Math.Round((1-f.GrainMix)*100)+" / "+Math.Round(f.GrainMix*100)):k==18?MasterFilter.Label(f.Filter):k==1?(f.ReverbSeconds>=60?(f.ReverbSeconds/60).ToString("0.0")+"m":f.ReverbSeconds.ToString("0.0")+"s"):k==3?f.DelayLabel:k==6||k==16?(f.GrainSize*1000).ToString("0")+"ms":k==7||k==11?f.GrainPitch.ToString("+0.0;-0.0;0"):k==10?((f.GrainMode==1?f.Position:f.CloudWindow)*1000).ToString("0")+"ms":k==12?(f.CloudFeedback*100).ToString("+0;-0;0")+"%":(Get(f,k)*100*(k==4?.85:1)).ToString("0")+"%";}
}
}
